import{_ as e,o as a,c as o,ag as d}from"./chunks/framework.NE9FR4AF.js";const p=JSON.parse('{"title":"〔大綱提案〕宇浩輸入平臺用户指南","description":"","frontmatter":{},"headers":[],"relativePath":"zht/docs/yume.md","filePath":"zht/docs/yume.md"}'),r={name:"zht/docs/yume.md"};function l(c,t,i,h,n,s){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="〔大綱提案〕宇浩輸入平臺用户指南" tabindex="-1">〔大綱提案〕宇浩輸入平臺用户指南 <a class="header-anchor" href="#〔大綱提案〕宇浩輸入平臺用户指南" aria-label="Permalink to &quot;〔大綱提案〕宇浩輸入平臺用户指南&quot;">​</a></h1><div class="danger custom-block"><p class="custom-block-title">這是待審的大綱，不是成稿</p><p>本文件目前只有骨架和每節的寫作要點，供作者過目調整。定稿後本段連同所有〔注〕一併删除。</p><p>調整方式：直接改標題、增删小節、在〔注〕裏批註即可。確認後我按此大綱寫成完整正文。</p></div><div class="info custom-block"><p class="custom-block-title">通篇約定（供審閲）</p><ul><li><strong>主角是 Windows 便攜版</strong>。所有截圖、按鍵、菜單路徑以便攜版爲準；安裝版（TSF）與便攜版的差異只在確有差異處用提示框標出，不另開章節重複。</li><li><strong>macOS 另有平行小節</strong>，只寫安裝與鍵位差異，功能不重述。</li><li><strong>Linux（fcitx5）尚未實作</strong>，只在「其他平臺」一句帶過，不列功能。</li><li>一至三章面向所有用户，力求短；第四章起爲進階，細節和坑都收在這裏。</li><li>截圖占位以 <code>&lt;!-- 截圖：… --&gt;</code> 標出，圖片統一放 <code>yu/src/public/yume/</code> 下，引用寫 <code>/yume/xxx.webp</code>。</li><li>用詞遵《<a href="/zht/docs/concepts.html">瓊林擷英</a>》：上屏、候選、選重、簡碼、全碼、字根、自分割。</li><li>文風和用語遵《<a href="/zht/docs/concepts.html">瓊林擷英</a>》，大陸用語。</li></ul></div><hr><h2 id="開篇-宇浩輸入平臺是什麼" tabindex="-1">開篇：宇浩輸入平臺是什麼 <a class="header-anchor" href="#開篇-宇浩輸入平臺是什麼" aria-label="Permalink to &quot;開篇：宇浩輸入平臺是什麼&quot;">​</a></h2><p>〔注：三四段，不寫成技術説明。要點——〕</p><ul><li>宇浩輸入平臺（Yume）是宇浩自研的<strong>原生輸入法程序</strong>：一個 Rust 內核 ＋ 各平臺原生界面，不依賴 Rime、不依賴任何第三方輸入法。下載即用，不需要部署、不需要編輯配置文件。</li><li>它與《<a href="/zht/docs/install.html">各平臺下載和安裝</a>》所講的 <strong>Rime 掛載方案並列，而非取代</strong>。想要 Rime 的生態與可配置性，走那條路；想要開箱即用、設置全在菜單裏，走這條路。碼表、拆分、字集三者兩邊同源。</li><li>靈明、星陳、卿雲、日月、拼音五個方案內置，隨時切換；亦可上傳自己的碼表編成方案。</li><li>一句話點題：<strong>確定帶來自由</strong>——每個漢字基本對應唯一編碼，打字不必停下來挑字。〔注：此處刻意不提「無需空格」，那是自定碼方案一家的特性，見 2.1。〕</li></ul><hr><h2 id="一、安裝" tabindex="-1">一、安裝 <a class="header-anchor" href="#一、安裝" aria-label="Permalink to &quot;一、安裝&quot;">​</a></h2><h3 id="_1-1-選哪個版本" tabindex="-1">1.1 選哪個版本 <a class="header-anchor" href="#_1-1-選哪個版本" aria-label="Permalink to &quot;1.1 選哪個版本&quot;">​</a></h3><p>〔注：一張三行小表，讀者掃一眼就能決定。列：免安裝／需管理員／內嵌輸入欄／適合誰。〕</p><table><thead><tr><th>版本</th><th>是否需要安裝</th><th>適合</th></tr></thead><tbody><tr><td><strong>Windows 便攜版</strong></td><td>解壓即用</td><td>絕大多數人；公司電腦、無管理員權限、U 盤</td></tr><tr><td><strong>Windows 安裝版（TSF）</strong></td><td>需管理員，一次性</td><td>想要內嵌輸入欄、想讓系統把它當正式鍵盤</td></tr><tr><td><strong>macOS 版</strong></td><td>拖進文件夾</td><td>Mac 用户</td></tr></tbody></table><p>〔注：明確寫一句「拿不定主意就用便攜版」，並説明兩者功能已齊平，差別只有內嵌輸入欄一項。〕</p><h3 id="_1-2-下載" tabindex="-1">1.2 下載 <a class="header-anchor" href="#_1-2-下載" aria-label="Permalink to &quot;1.2 下載&quot;">​</a></h3><p>〔注：三個渠道並列，各給一句適用説明。〕</p><ul><li><a href="https://github.com/forfudan/yume-release/releases" target="_blank" rel="noreferrer">GitHub 發佈頁</a>——版本最全、最新</li><li><a href="http://zhuyuhao.ysepan.com/" target="_blank" rel="noreferrer">永碩網盤</a>——訪問 GitHub 不便時</li><li>QQ 交流羣文件——<a href="https://qm.qq.com/q/1hYF5Shdbg" target="_blank" rel="noreferrer">點此加羣</a></li></ul><h3 id="_1-3-windows-便攜版-解壓即用" tabindex="-1">1.3 Windows 便攜版：解壓即用 <a class="header-anchor" href="#_1-3-windows-便攜版-解壓即用" aria-label="Permalink to &quot;1.3 Windows 便攜版：解壓即用&quot;">​</a></h3><p>〔注：編號步驟，不超過五步。要點——〕</p><ol><li>下載 <code>Yume-Portable-*.zip</code>，<strong>整個 <code>Yume</code> 文件夾</strong>解壓到可寫的位置（桌面、文檔、U 盤皆可）。</li><li>雙擊 <code>YumePortable.exe</code>。</li><li>任務欄右下角出現<strong>紫色「宇」圖標</strong>即已就緒；直接在任何輸入框打字。</li><li>右鍵該圖標＝全部設置。</li></ol><div class="warning custom-block"><p class="custom-block-title">不要解壓到 <code>C:\\Program Files</code></p><p>〔注：解釋——便攜版要在自己的文件夾裏寫設置與詞庫，該處無寫權限；直接在壓縮包預覽窗口裏運行同理。程序會當場報錯而非默默丟失設置。〕</p></div><h3 id="_1-4-windows-安裝版-tsf" tabindex="-1">1.4 Windows 安裝版（TSF） <a class="header-anchor" href="#_1-4-windows-安裝版-tsf" aria-label="Permalink to &quot;1.4 Windows 安裝版（TSF）&quot;">​</a></h3><p>〔注：三步。下載 <code>Yume-Setup-*.exe</code> → 運行（SmartScreen「更多信息 ▸ 仍要運行」，説明原因：安裝包未做代碼簽名）→ 設置 ▸ 時間和語言 ▸ 語言和區域 ▸ 中文 ▸ 語言選項 ▸ 鍵盤 ▸ 添加鍵盤 ▸ 宇浩。Win+空格切換。托盤圖標爲<strong>藍色</strong>。〕</p><h3 id="_1-5-macos" tabindex="-1">1.5 macOS <a class="header-anchor" href="#_1-5-macos" aria-label="Permalink to &quot;1.5 macOS&quot;">​</a></h3><p>〔注：平行小節，同樣三步。要點——<code>Yume.app</code> 拖進 <code>~/Library/Input Methods/</code>；首次安裝需<strong>註銷重新登入一次</strong>；系統設置 ▸ 鍵盤 ▸ 輸入法 ▸ ＋ ▸ 中文 ▸ 靈明 ▸ 添加；⌃空格切換。更新時不需再註銷。菜單在系統菜單欄的輸入法圖標下。〕</p><h3 id="_1-6-更新與卸載" tabindex="-1">1.6 更新與卸載 <a class="header-anchor" href="#_1-6-更新與卸載" aria-label="Permalink to &quot;1.6 更新與卸載&quot;">​</a></h3><p>〔注：小表或短列表。要點——〕</p><ul><li>便攜版：托盤菜單「檢查本輸入法更新包」只<strong>提示</strong>並打開下載頁（它蓋不掉正在運行的自己）；下新包後把 <code>Resources\\</code> 與 exe 覆蓋舊的即可，<strong><code>UserData\\</code> 不在壓縮包內，設置與詞庫不會丟</strong>。卸載＝删文件夾。</li><li>安裝版：托盤菜單「檢查本輸入法更新包」直接下載並安裝。卸載走「應用和功能」。</li><li>macOS：菜單裏檢查更新，自動下載安裝。</li></ul><h3 id="_1-7-其他平臺" tabindex="-1">1.7 其他平臺 <a class="header-anchor" href="#_1-7-其他平臺" aria-label="Permalink to &quot;1.7 其他平臺&quot;">​</a></h3><p>〔注：兩三句帶過。網頁版 <a href="https://yume.shurufa.app" target="_blank" rel="noreferrer">https://yume.shurufa.app</a> 免安裝可試（功能爲子集）；Linux（fcitx5）內核已就緒、界面尚未實作。〕</p><hr><h2 id="二、開始輸入" tabindex="-1">二、開始輸入 <a class="header-anchor" href="#二、開始輸入" aria-label="Permalink to &quot;二、開始輸入&quot;">​</a></h2><p>〔注：本章是全文最該短的一章。目標——讀完就能打字。〕</p><h3 id="_2-1-先認清你的方案屬於哪一類" tabindex="-1">2.1 先認清你的方案屬於哪一類 <a class="header-anchor" href="#_2-1-先認清你的方案屬於哪一類" aria-label="Permalink to &quot;2.1 先認清你的方案屬於哪一類&quot;">​</a></h3><p>〔注：本章的樞紐。宇浩四個形碼方案分兩家，分界是「一個字的編碼怎麼結束」；節奏不同，後面 3.3 上屏模式與 6.1 手動切分還要各用一次，故放在最前。〕</p><table><thead><tr><th></th><th>星陳・卿雲</th><th>靈明・日月</th></tr></thead><tbody><tr><td>類型</td><td>限長方案</td><td>自定碼方案（前綴碼）</td></tr><tr><td>最大碼長</td><td>4</td><td>靈明 4、日月 5</td></tr><tr><td><strong>一個字怎麼結束</strong></td><td>打滿最大碼長，或按空格</td><td>末碼是韻碼，編碼自報結束</td></tr><tr><td>編碼分割</td><td>不唯一，需分隔</td><td>唯一</td></tr><tr><td>手感近於</td><td>五筆、鄭碼</td><td>——</td></tr></tbody></table><p>〔注：表下附一句辨析，免得與《瓊林擷英》打架——<strong>兩類方案都是限長的</strong>，自定碼方案只是在限長之外<strong>額外</strong>具備自定屬性；這裏按「靠什麼結束」分家。術語見《瓊林擷英》的<a href="/zht/docs/concepts.html#限長">限長</a>與<a href="/zht/docs/concepts.html#前綴碼">前綴碼</a>。〕</p><p>〔注：再一句——拼音方案不在此表，它只走整句模式，見 3.3。〕</p><h3 id="_2-2-限長方案-星陳、卿雲" tabindex="-1">2.2 限長方案：星陳、卿雲 <a class="header-anchor" href="#_2-2-限長方案-星陳、卿雲" aria-label="Permalink to &quot;2.2 限長方案：星陳、卿雲&quot;">​</a></h3><p>〔注：要點——〕</p><ul><li><p>全碼四碼。<strong>打滿四碼自動上屏</strong>，不必再按空格。</p></li><li><p>不滿四碼的簡碼，<strong>按空格上屏</strong>。此處的空格既是分隔符，也可視作簡碼的最後一碼。</p></li><li><p>例子：以星陳打「不用等候」四字——</p><table><thead><tr><th>字</th><th>編碼</th><th>碼長</th><th>怎麼上屏</th></tr></thead><tbody><tr><td>不</td><td><code>v</code></td><td>一級簡碼</td><td>按空格</td></tr><tr><td>用</td><td><code>sy</code></td><td>二級簡碼</td><td>按空格</td></tr><tr><td>等</td><td><code>gh</code></td><td>二級簡碼</td><td>按空格</td></tr><tr><td>候</td><td><code>eubj</code></td><td>全碼</td><td>滿四碼，自動上屏</td></tr></tbody></table><p>〔注：已對照 Yume 隨包碼表 <code>data/xing.txt</code> 覈實，四字皆傳承字，陸標簡碼與繁簡通打兩表通用。定稿時把整串實際按鍵寫出來：<code>v␣sy␣gh␣eubj</code>。〕</p></li></ul><h3 id="_2-3-自定碼方案-靈明、日月" tabindex="-1">2.3 自定碼方案：靈明、日月 <a class="header-anchor" href="#_2-3-自定碼方案-靈明、日月" aria-label="Permalink to &quot;2.3 自定碼方案：靈明、日月&quot;">​</a></h3><p>〔注：要點——〕</p><ul><li>字根的末碼落在 <code>a e i o u</code> 五個韻碼上。韻碼與輔音兩區互斥，所以<strong>編碼自己知道自己在哪結束</strong>——連續敲下去即可，中途無需空格。</li><li>例子：<code>eioua</code> → 的是我不了。五個字一氣呵成，中間一次停頓也沒有。</li><li>韻碼之外，打滿最大碼長同樣自動上屏（靈明 4、日月 5）。</li><li>一句話收束：這就是首頁所説的「確定帶來自由」。</li></ul><h3 id="_2-4-以下各節-兩類方案通用" tabindex="-1">2.4 以下各節，兩類方案通用 <a class="header-anchor" href="#_2-4-以下各節-兩類方案通用" aria-label="Permalink to &quot;2.4 以下各節，兩類方案通用&quot;">​</a></h3><p>〔注：這是一行過渡句，不是小節標題，定稿時併入 2.5 開頭。作用是告訴讀者分家到此爲止。〕</p><h3 id="_2-5-候選、選重與翻頁" tabindex="-1">2.5 候選、選重與翻頁 <a class="header-anchor" href="#_2-5-候選、選重與翻頁" aria-label="Permalink to &quot;2.5 候選、選重與翻頁&quot;">​</a></h3><p>〔注：小表。〕</p><table><thead><tr><th>鍵</th><th>作用</th></tr></thead><tbody><tr><td><code>1</code>–<code>9</code></td><td>選第 1–9 個候選</td></tr><tr><td><code>;</code></td><td>選第 2 個候選</td></tr><tr><td><code>&#39;</code></td><td>選第 3 個候選</td></tr><tr><td><code>←</code> <code>→</code></td><td>上／下一頁（豎排佈局）</td></tr><tr><td><code>↑</code> <code>↓</code></td><td>上／下一頁（橫排佈局）</td></tr></tbody></table><p>〔注：附一句——宇浩重碼極低，多數字一次到位，選重鍵平時用不上。〕</p><h3 id="_2-6-空格與回車" tabindex="-1">2.6 空格與回車 <a class="header-anchor" href="#_2-6-空格與回車" aria-label="Permalink to &quot;2.6 空格與回車&quot;">​</a></h3><p>〔注：兩條規則，寫清楚差別，這是新手最易困惑處。〕</p><ul><li><strong>空格</strong>：有候選 → 上屏高亮候選；有編碼但無候選（半段碼）→ <strong>原樣上屏編碼</strong>；無編碼 → 打出一個空格。</li><li><strong>回車</strong>：緩衝非空時，一律把編碼<strong>原樣上屏</strong>（打英文單詞時很順手）。</li><li><strong>退格</strong>：逐碼删。<strong>Esc</strong>：清空。</li></ul><h3 id="_2-7-中英與標點" tabindex="-1">2.7 中英與標點 <a class="header-anchor" href="#_2-7-中英與標點" aria-label="Permalink to &quot;2.7 中英與標點&quot;">​</a></h3><p>〔注：要點——〕</p><ul><li><strong>單擊 Shift</strong> 切中／英。</li><li>組字中打<strong>大寫字母</strong>直接進臨時英數，打完空格上屏。</li><li>空緩衝時首鍵爲數字或 <code>+</code> <code>-</code> 進<strong>臨時數字模式</strong>，<code>123.45%</code> 之類原樣輸出，不轉全角。</li><li>中文模式下英文標點自動轉全角中文標點，引號自動開合。有編碼時先上屏首選再出標點。</li></ul><h3 id="_2-8-用-z-反查拼音、叫回歷史" tabindex="-1">2.8 用 <code>z</code> 反查拼音、叫回歷史 <a class="header-anchor" href="#_2-8-用-z-反查拼音、叫回歷史" aria-label="Permalink to &quot;2.8 用 `z` 反查拼音、叫回歷史&quot;">​</a></h3><p>〔注：兩句。空緩衝按 <code>z</code> 進拼音反查，可整句解碼；<code>z</code> 亦可叫回最近上屏過的內容。〕</p><h3 id="_2-9-按鍵速查表" tabindex="-1">2.9 按鍵速查表 <a class="header-anchor" href="#_2-9-按鍵速查表" aria-label="Permalink to &quot;2.9 按鍵速查表&quot;">​</a></h3><p>〔注：本章結尾放一張完整按鍵表，讀者可截圖存手機。含 a–y、1–9、<code>;</code>、<code>&#39;</code>、空格、回車、退格、Esc、Shift、Tab、⇧Tab、方向鍵、<code>/</code>、<code>;</code>（空緩衝）、<code>`</code>、Ctrl+空格。〕</p><hr><h2 id="三、常用設置" tabindex="-1">三、常用設置 <a class="header-anchor" href="#三、常用設置" aria-label="Permalink to &quot;三、常用設置&quot;">​</a></h2><h3 id="_3-1-三條路通同一個開關" tabindex="-1">3.1 三條路通同一個開關 <a class="header-anchor" href="#_3-1-三條路通同一個開關" aria-label="Permalink to &quot;3.1 三條路通同一個開關&quot;">​</a></h3><p>〔注：先講機制，後面各節就不必反覆説「怎麼打開」。〕</p><table><thead><tr><th>入口</th><th>怎麼用</th><th>適合</th></tr></thead><tbody><tr><td><strong>托盤菜單</strong></td><td>右鍵任務欄「宇」圖標</td><td>第一次設置、看全貌</td></tr><tr><td><strong>斜線命令</strong></td><td>空緩衝打 <code>/</code>，再打命令名，如 <code>/mode</code></td><td>打字中途、手不離鍵盤</td></tr><tr><td><strong>快捷鍵</strong></td><td><code>Ctrl+Shift+</code> 某鍵</td><td>高頻切換</td></tr></tbody></table><h3 id="_3-2-方案" tabindex="-1">3.2 方案 <a class="header-anchor" href="#_3-2-方案" aria-label="Permalink to &quot;3.2 方案&quot;">​</a></h3><p>〔注：五個內置方案一句話各一。靈明／星陳／卿雲／日月爲宇浩系列形碼，拼音爲全拼（可切雙拼）。切換：<code>Ctrl+Shift+N</code> 在形碼間循環，<code>Ctrl+Shift+I</code> 進出拼音。各方案的字根與規則指向 /zht/docs/ling 等既有頁面，本文不重複。〕</p><h3 id="_3-3-上屏模式-三選一" tabindex="-1">3.3 上屏模式：三選一 <a class="header-anchor" href="#_3-3-上屏模式-三選一" aria-label="Permalink to &quot;3.3 上屏模式：三選一&quot;">​</a></h3><p>〔注：本節是全文最值得寫清楚的一節，因爲它決定打字手感。三種模式各給「怎麼動」「適合誰」。〕</p><table><thead><tr><th>模式</th><th>行爲</th><th>適合</th></tr></thead><tbody><tr><td><strong>頂字上屏模式</strong>〔默認〕</td><td>延遲一字，下一字的編碼把前一字「頂」上屏</td><td>絕大多數人，各版本出廠值</td></tr><tr><td><strong>自動上屏模式</strong></td><td>編碼一旦唯一確定即上屏</td><td>追求無停頓、盲打</td></tr><tr><td><strong>整句輸入模式</strong></td><td>連打一串，由語言模型切分成句，一次上屏</td><td>長句、詞語多、拼音方案</td></tr></tbody></table><p>〔注：<strong>頂字上屏爲各版本出廠默認</strong>，故列在第一行；正文要明説這一點，讀者才知道自己現在處於哪一檔。<code>Ctrl+Shift+M</code> 循環，<code>/mode</code>。〕</p><div class="warning custom-block"><p class="custom-block-title">整句模式下，兩類方案的行爲不同</p><p>〔注：承 2.1，這是那條分界線的第二次現身，必須寫。要點——<strong>限長方案（星陳、卿雲）在整句模式下只認全碼</strong>，簡碼不進整句；一碼字亦不參與。原因是沒有韻碼作邊界，簡碼只是全碼的前綴，整句無從判斷它到哪結束（引擎的 <code>fluency_full_code_only</code>）。<strong>自定碼方案（靈明、日月）沒有這個限制</strong>，簡碼照用。星陳、卿雲用户若想在整句裏用簡碼，辦法是 6.1 的手動切分。〕</p></div><h3 id="_3-4-字集-過濾與排序" tabindex="-1">3.4 字集：過濾與排序 <a class="header-anchor" href="#_3-4-字集-過濾與排序" aria-label="Permalink to &quot;3.4 字集：過濾與排序&quot;">​</a></h3><p>〔注：兩個獨立的開關，各四檔，別混爲一談。過濾＝不顯示；排序＝顯示但後置。〕</p><ul><li>過濾：全部漢字／僅常用漢字／僅簡化漢字／僅傳統漢字／僅自定義字集。<code>Ctrl+Shift+0</code> 循環。</li><li>排序：原始排序／常用字優先／簡化字優先／傳統字優先／自定義字集優先。無快捷鍵，走菜單。</li><li>一句話給建議：只打現代簡體 → 過濾「僅簡化漢字」；打古籍 → 過濾「全部」＋排序「傳統字優先」。</li></ul><h3 id="_3-5-單字派" tabindex="-1">3.5 單字派 <a class="header-anchor" href="#_3-5-單字派" aria-label="Permalink to &quot;3.5 單字派&quot;">​</a></h3><p>〔注：三檔。字詞同出（默認）／主單副詞／嚴格單字。<code>Ctrl+Shift+D</code>。「主單副詞」下具體顯示哪類詞語另有五個勾選，指向 4.5 節，此處不展開。〕</p><h3 id="_3-6-注解" tabindex="-1">3.6 注解 <a class="header-anchor" href="#_3-6-注解" aria-label="Permalink to &quot;3.6 注解&quot;">​</a></h3><p>〔注：三檔：關閉／二重（拆分・分節碼）／多重（＋讀音・字義・字集・Unicode 碼位）。<code>Ctrl+Shift+/</code>；組字中單按 <code>/</code> 亦可循環（拼音方案除外）。學習期建議開多重。〕</p><h3 id="_3-7-候選面板外觀" tabindex="-1">3.7 候選面板外觀 <a class="header-anchor" href="#_3-7-候選面板外觀" aria-label="Permalink to &quot;3.7 候選面板外觀&quot;">​</a></h3><p>〔注：合併爲一節，逐條一句話，都是「設一次就不動」的。〕</p><ul><li>候選佈局：傳統豎排／簡約橫排／極簡內嵌（<code>Ctrl+Shift+L</code>）。<strong>極簡內嵌僅安裝版與 macOS 有</strong>。</li><li>每頁候選數 3–9：<code>Ctrl+Shift+3</code>–<code>Ctrl+Shift+9</code>。</li><li>序號欄、註釋欄、註腳欄的顯隱。</li><li>半角／全角標點：<code>Ctrl+Shift+.</code>。</li><li>預測候選（僅差韻碼即成字的提示）：<code>Ctrl+Shift+Y</code>。</li><li>空格簡碼、變體漢字的顯隱：<code>Ctrl+Shift+K</code> 等。</li></ul><h3 id="_3-8-內嵌輸入欄" tabindex="-1">3.8 內嵌輸入欄 <a class="header-anchor" href="#_3-8-內嵌輸入欄" aria-label="Permalink to &quot;3.8 內嵌輸入欄&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">本節僅適用於 Windows 安裝版與 macOS</p><p>〔注：説明原因——便攜版靠全局鍵盤鈎子工作，宿主程序裏沒有可供繪製的預編輯區，故無「內嵌輸入欄」「內嵌時預覽首選」「極簡內嵌佈局」三項。這是設計取捨，不是缺陷；便攜版其餘功能與安裝版齊平。〕</p></div><p>〔注：正文兩三句——內嵌輸入欄把編碼直接畫在光標處而非浮動面板上；「內嵌時預覽首選」進一步把首選漢字而非編碼畫在那裏。菜單開關，無快捷鍵。〕</p><h3 id="_3-9-還原默認" tabindex="-1">3.9 還原默認 <a class="header-anchor" href="#_3-9-還原默認" aria-label="Permalink to &quot;3.9 還原默認&quot;">​</a></h3><p>〔注：一句。菜單「還原默認設置」或 <code>/default</code>。〕</p><hr><h2 id="四、進階功能" tabindex="-1">四、進階功能 <a class="header-anchor" href="#四、進階功能" aria-label="Permalink to &quot;四、進階功能&quot;">​</a></h2><p>〔注：本章起面向願意折騰的用户。每節仍以「它解決什麼問題」開頭，再講怎麼用。〕</p><h3 id="_4-1-快捷字符-引導" tabindex="-1">4.1 快捷字符（<code>;</code> 引導） <a class="header-anchor" href="#_4-1-快捷字符-引導" aria-label="Permalink to &quot;4.1 快捷字符（`;` 引導）&quot;">​</a></h3><p>〔注：空緩衝按 <code>;</code> 打開 26 鍵對照面板，再按字母即上屏一段文本——標點、符號、漢字或整段話皆可。面板另有 <code>;</code> <code>,</code> <code>.</code> <code>$</code> 四個固定條目。菜單「編輯快捷字符表」自定義；26 條全空即關閉此功能。〕</p><h3 id="_4-2-符號與-unicode" tabindex="-1">4.2 符號與 Unicode <a class="header-anchor" href="#_4-2-符號與-unicode" aria-label="Permalink to &quot;4.2 符號與 Unicode&quot;">​</a></h3><p>〔注：<code>/</code> 引導符號命令（<code>/tab</code> 插制表符、<code>/version</code> 打版本號等）；<code>//</code> 後接十六進制碼位直接輸出該 Unicode 字符。宇浩系列另有 <code>fh</code> <code>jm</code> <code>py</code> <code>bd</code> <code>dy</code> <code>yj</code> <code>kk</code> 等編碼引導符，同 Rime 方案，鏈接到 install.md 對應段落，不重複列。〕</p><h3 id="_4-3-三個浮動面板" tabindex="-1">4.3 三個浮動面板 <a class="header-anchor" href="#_4-3-三個浮動面板" aria-label="Permalink to &quot;4.3 三個浮動面板&quot;">​</a></h3><p>〔注：一表帶過，各一句。都在候選高亮時按。〕</p><table><thead><tr><th>鍵</th><th>面板</th><th>用途</th></tr></thead><tbody><tr><td><code>Tab</code></td><td>查閱面板</td><td>單字查字統網，詞語查漢典</td></tr><tr><td><code>⇧Tab</code></td><td>相似部件九宮格</td><td>按拆分字根的子序列檢索同部件字，學習利器</td></tr><tr><td><code>←→</code> 或 <code>↑↓</code></td><td>更多候選格狀面板</td><td>一屏鋪開全部候選</td></tr></tbody></table><h3 id="_4-4-用户詞庫" tabindex="-1">4.4 用户詞庫 <a class="header-anchor" href="#_4-4-用户詞庫" aria-label="Permalink to &quot;4.4 用户詞庫&quot;">​</a></h3><p>〔注：菜單「編輯用户詞庫」或 <code>Ctrl+Shift+U</code>。表格式編輯，「字詞」列填內容，「用户編碼」列可留空（自動編碼）也可填多個（空格分隔）。<strong>每個方案各有一份</strong>，自定義方案亦然。用户詞庫中的詞語不受單字派限制，一律顯示。〕</p><h3 id="_4-5-更多詞語功能設置" tabindex="-1">4.5 更多詞語功能設置 <a class="header-anchor" href="#_4-5-更多詞語功能設置" aria-label="Permalink to &quot;4.5 更多詞語功能設置&quot;">​</a></h3><p>〔注：承接 3.5。主單副詞模式下，勾選要顯示哪幾類詞語（兩字／三字／四字／四字以上／白名單）——<strong>出廠五項全關</strong>，即開箱只出單字，要哪類自己勾。另有「靈明方案使用傳統構詞法」一項（僅靈明可見）。〕</p><h3 id="_4-6-自定義字集" tabindex="-1">4.6 自定義字集 <a class="header-anchor" href="#_4-6-自定義字集" aria-label="Permalink to &quot;4.6 自定義字集&quot;">​</a></h3><p>〔注：菜單「編輯自定義字集」。可勾七個現成字集（通用規範漢字、調和傳統漢字、香港常用字、常用與次常用國字、古籍通用規範漢字等）與 Unicode 區塊，再加白名單／黑名單。面板自帶「測試」框：粘進字符逐字告訴你會不會顯示、是哪一條勾選在起作用。定好之後配合 3.4 的「僅自定義字集」使用。〕</p><h3 id="_4-7-拼音與雙拼" tabindex="-1">4.7 拼音與雙拼 <a class="header-anchor" href="#_4-7-拼音與雙拼" aria-label="Permalink to &quot;4.7 拼音與雙拼&quot;">​</a></h3><p>〔注：<code>Ctrl+Shift+I</code> 進出拼音方案。雙拼<strong>七種</strong>預設：自然碼、微軟、搜狗、紫光、拼音加加、智能 ABC、國標，另有自定義佈局編輯器。<code>z</code> 反查與拼音方案共用同一套佈局設置。〕</p><p>〔注：<strong>不收小鶴雙拼，係版權考量，正文不必解釋，也不要寫成「暫未支持」</strong>——需要的人用自定義佈局自己配即可，正文可順帶點一句自定義佈局能配出任意方案。〕</p><h3 id="_4-8-幾個順手的小功能" tabindex="-1">4.8 幾個順手的小功能 <a class="header-anchor" href="#_4-8-幾個順手的小功能" aria-label="Permalink to &quot;4.8 幾個順手的小功能&quot;">​</a></h3><p>〔注：短列表，各一句。〕</p><ul><li><strong>注解上屏</strong> <code>Ctrl+Shift+A</code>：把高亮候選的注解（拆分、讀音、碼位等）當文本上屏。寫教程、發羣消息時很方便。</li><li><strong>截圖候選面板</strong> <code>Ctrl+Shift+J</code>：把當前候選面板 2× 重繪後複製到剪貼板。</li><li><strong>暫停／恢復輸入法</strong> <code>Ctrl+Space</code>：所有按鍵直通程序，托盤圖標轉灰。打遊戲、用快捷鍵密集的軟件時用。</li><li><strong>登入時自動啓動</strong>（僅便攜版）：托盤菜單勾選，只寫一個註册表值，取消即淨。</li></ul><h3 id="_4-9-便攜版引擎-安裝版用户" tabindex="-1">4.9 便攜版引擎（安裝版用户） <a class="header-anchor" href="#_4-9-便攜版引擎-安裝版用户" aria-label="Permalink to &quot;4.9 便攜版引擎（安裝版用户）&quot;">​</a></h3><p>〔注：安裝版托盤菜單有「使用便攜版引擎」一項，把打字交給便攜版助手——用於文字服務驅動不了的程序。開啓時會提示把系統鍵盤佈局切到英文，並解釋原因（否則系統選中的另一個輸入法仍會疊加自己的中英狀態與候選窗）。高權限窗口下該開關會被拒絕並説明。〕</p><hr><h2 id="五、自定義方案-用自己的碼表" tabindex="-1">五、自定義方案：用自己的碼表 <a class="header-anchor" href="#五、自定義方案-用自己的碼表" aria-label="Permalink to &quot;五、自定義方案：用自己的碼表&quot;">​</a></h2><p>〔注：本章面向方案作者與折騰派。可寫得稍長，但仍分步。〕</p><h3 id="_5-1-能做到什麼" tabindex="-1">5.1 能做到什麼 <a class="header-anchor" href="#_5-1-能做到什麼" aria-label="Permalink to &quot;5.1 能做到什麼&quot;">​</a></h3><p>〔注：一段。上傳一份碼表文件，Yume 當場編譯成一個可用方案：最大碼長、自分割字母、字根編碼、取碼規則全部由碼表<strong>反推</strong>（Zhu Bootstrapping Algorithm），不需要你寫任何配置。編好之後與內置方案同等待遇——有自己的用户詞庫、能用注解、能切換。〕</p><h3 id="_5-2-碼表格式" tabindex="-1">5.2 碼表格式 <a class="header-anchor" href="#_5-2-碼表格式" aria-label="Permalink to &quot;5.2 碼表格式&quot;">​</a></h3><p>〔注：每行 <code>漢字&lt;Tab&gt;編碼</code> 或 <code>編碼&lt;空格&gt;漢字</code>，UTF-8。文件名第一個點之前即方案名。〕</p><p>〔注：<strong>寫正文時務必記得</strong>——<code>&lt;Tab&gt;</code> 這類尖括號一旦裸露在 Markdown 裏，VitePress 會當成 Vue 組件而編譯失敗，全篇凡出現處一律包進反引號。〕</p><h3 id="_5-3-三步走" tabindex="-1">5.3 三步走 <a class="header-anchor" href="#_5-3-三步走" aria-label="Permalink to &quot;5.3 三步走&quot;">​</a></h3><p>〔注：編號步驟。上傳 → 確認參數（帶「⚠」的幾項是碼表自己也説不清、最該過目的）→ 編譯完成，報告最大碼長、自分割字母、碼表條目數、還原率。〕</p><h3 id="_5-4-給得越多-推得越準" tabindex="-1">5.4 給得越多，推得越準 <a class="header-anchor" href="#_5-4-給得越多-推得越準" aria-label="Permalink to &quot;5.4 給得越多，推得越準&quot;">​</a></h3><p>〔注：這是本章的關鍵一節，用一張遞進表講清楚。〕</p><table><thead><tr><th>你提供的</th><th>系統還要推的</th><th>拆分注解質量</th></tr></thead><tbody><tr><td>只有碼表</td><td>拆分 ＋ 字根編碼 ＋ 取碼規則</td><td>反推，還原率約八成</td></tr><tr><td>碼表 ＋ 拆分表</td><td>字根編碼 ＋ 取碼規則</td><td>拆分完全以你的表爲準</td></tr><tr><td>碼表 ＋ 拆分表 ＋ 字根表</td><td>只剩取碼規則</td><td>編碼一個字母都不會被推翻</td></tr></tbody></table><p>〔注：附兩條格式説明——拆分表每行 <code>漢字&lt;Tab&gt;拆分序列</code>，宇浩自家 <code>chaifen.txt</code> 可直接用；字根表每行 <code>字根&lt;Tab&gt;編碼</code>，字根寫法須與拆分表一致（一邊「氵」一邊「水」就對不上）。〕</p><h3 id="_5-5-方案管理" tabindex="-1">5.5 方案管理 <a class="header-anchor" href="#_5-5-方案管理" aria-label="Permalink to &quot;5.5 方案管理&quot;">​</a></h3><p>〔注：命名、重新上傳、配置、撤銷（只能退一步）、删除、從方案列表隱藏、注解中隱藏拆分／編碼。槽位有上限。〕</p><hr><h2 id="六、細節與疑難" tabindex="-1">六、細節與疑難 <a class="header-anchor" href="#六、細節與疑難" aria-label="Permalink to &quot;六、細節與疑難&quot;">​</a></h2><p>〔注：本章收全部「需要留神」的點。體例統一：<strong>現象 → 原因 → 怎麼辦</strong>，每條不超過一段。〕</p><h3 id="_6-1-整句模式-用-手動切分" tabindex="-1">6.1 整句模式：用 <code>`</code> 手動切分 <a class="header-anchor" href="#_6-1-整句模式-用-手動切分" aria-label="Permalink to &quot;6.1 整句模式：用 `` ` `` 手動切分&quot;">​</a></h3><p>〔注：本節值得寫足，是全文最技術的一處，也是老用户最需要的。要點——〕</p><ul><li>承 2.1 那條分界線的第三次現身。整句模式下引擎要自己把一串字母切成段：**自定碼方案（靈明、日月）**的切分由韻碼決定，引擎不必猜；<strong>限長方案（星陳、卿雲）沒有韻碼，字母是真歧義，引擎只能猜</strong>。</li><li>按<strong>反引號 <code>`</code></strong>（數字 1 左邊那個鍵）即可親手畫一道段界，把猜測變成事實。與 Rime 方案的「<a href="/zht/docs/install.html#精確造詞">精確造詞</a>」是同一個鍵、同一個意思。</li><li>它做兩件事：①<strong>這個字到此爲止</strong>——沒有任何單字候選能跨過這道界；②<strong>界前那一段是完整的</strong>，因此 3.3 提到的「限長方案整句只認全碼」就此解除，簡碼重新可用。舉例：卿雲的 <code>um`qf`jtp</code> 三個簡碼打出「庆丰收」。</li><li>補一句原理註腳：<code>`</code> 不是韻碼，它不進碼表、不參與查詢，所以它能對所有方案通用而永不與方案自己的字母打架。</li><li>註：連按兩次等同一次（幂等）。</li><li>〔注：本節寫足，但要在 3.3 的提示框裏留一句「辦法見 6.1」的指路，讓星陳、卿雲用户不至於漏掉。〕</li></ul><h3 id="_6-2-打錯了-整段編碼留在原地" tabindex="-1">6.2 打錯了，整段編碼留在原地 <a class="header-anchor" href="#_6-2-打錯了-整段編碼留在原地" aria-label="Permalink to &quot;6.2 打錯了，整段編碼留在原地&quot;">​</a></h3><p>〔注：現象——輸入非法／死路編碼時，整段原樣留在編碼區不被切碎。原因——<strong>不做空碼回退</strong>，寧可讓你退格改，也不把它切成不合法的分段。這是刻意設計。〕</p><h3 id="_6-3-候選面板被開始菜單擋住" tabindex="-1">6.3 候選面板被開始菜單擋住 <a class="header-anchor" href="#_6-3-候選面板被開始菜單擋住" aria-label="Permalink to &quot;6.3 候選面板被開始菜單擋住&quot;">​</a></h3><p>〔注：現象——在開始菜單、任務欄搜索框裏打字，面板看不見。原因——那些界面畫在比普通窗口更高的層級。現狀——兩個 Windows 版都已改爲<strong>讓位</strong>（把面板挪開而非疊上去），能正常輸入；徹底蓋過去需要簽名的高權限進程，屬未來工作。〕</p><h3 id="_6-4-便攜版與安裝版同時運行" tabindex="-1">6.4 便攜版與安裝版同時運行 <a class="header-anchor" href="#_6-4-便攜版與安裝版同時運行" aria-label="Permalink to &quot;6.4 便攜版與安裝版同時運行&quot;">​</a></h3><p>〔注：現象——每個按鍵被處理兩次，中英狀態各自翻轉、對不齊。原因——兩者都掛鍵盤鈎子。辦法——只留一個；便攜版啓動時偵測到安裝版會主動詢問。附一句：托盤圖標<strong>紫色＝便攜版、藍色＝安裝版、灰色＝已暫停</strong>，一眼就知道是誰在打字。〕</p><h3 id="_6-5-便攜版的文件放在哪" tabindex="-1">6.5 便攜版的文件放在哪 <a class="header-anchor" href="#_6-5-便攜版的文件放在哪" aria-label="Permalink to &quot;6.5 便攜版的文件放在哪&quot;">​</a></h3><p>〔注：<code>Resources\\</code> 唯讀、隨更新覆蓋；<code>UserData\\</code> 是你的設置與詞庫，不在壓縮包內、更新不會被碰。托盤菜單「打開用户文件夾」直達。USB 拔插後只要相對位置不變即可用。〕</p><h3 id="_6-6-高權限窗口下打不了字" tabindex="-1">6.6 高權限窗口下打不了字 <a class="header-anchor" href="#_6-6-高權限窗口下打不了字" aria-label="Permalink to &quot;6.6 高權限窗口下打不了字&quot;">​</a></h3><p>〔注：現象——在以管理員身份運行的程序裏，便攜版無反應。原因——Windows 的權限隔離不讓普通權限的鈎子看到高權限窗口的按鍵。辦法——改用安裝版。〕</p><h3 id="_6-7-剛更新完-某個程序還是舊行爲" tabindex="-1">6.7 剛更新完，某個程序還是舊行爲 <a class="header-anchor" href="#_6-7-剛更新完-某個程序還是舊行爲" aria-label="Permalink to &quot;6.7 剛更新完，某個程序還是舊行爲&quot;">​</a></h3><p>〔注：僅安裝版。原因——Windows 把輸入法 DLL 常駐在每個用過它的進程裏。辦法——重開那個程序即可。〕</p><h3 id="_6-8-出了問題怎麼反饋" tabindex="-1">6.8 出了問題怎麼反饋 <a class="header-anchor" href="#_6-8-出了問題怎麼反饋" aria-label="Permalink to &quot;6.8 出了問題怎麼反饋&quot;">​</a></h3><p>〔注：診斷日誌 <code>yume.log</code> 的位置；GitHub Issues；QQ 羣。〕</p><hr><h2 id="附錄" tabindex="-1">附錄 <a class="header-anchor" href="#附錄" aria-label="Permalink to &quot;附錄&quot;">​</a></h2><h3 id="附錄-a-全部快捷鍵" tabindex="-1">附錄 A 全部快捷鍵 <a class="header-anchor" href="#附錄-a-全部快捷鍵" aria-label="Permalink to &quot;附錄 A 全部快捷鍵&quot;">​</a></h3><p>〔注：一張完整表，按功能分組。含 <code>Ctrl+Shift+0</code>、<code>3</code>–<code>9</code>、<code>A</code> <code>D</code> <code>H</code> <code>I</code> <code>J</code> <code>K</code> <code>L</code> <code>M</code> <code>N</code> <code>U</code> <code>Y</code> <code>.</code> <code>/</code>、<code>Ctrl+Space</code>，以及組字中的單鍵 <code>0</code> <code>/</code> <code>Tab</code> <code>⇧Tab</code> 方向鍵。macOS 一欄用 <code>⌃⇧</code>。〕</p><h3 id="附錄-b-全部斜線命令" tabindex="-1">附錄 B 全部斜線命令 <a class="header-anchor" href="#附錄-b-全部斜線命令" aria-label="Permalink to &quot;附錄 B 全部斜線命令&quot;">​</a></h3><p>〔注：一張表，命令族 → 主名 ＋ 常用別名。〕</p><h3 id="附錄-c-便攜版與安裝版功能對照" tabindex="-1">附錄 C 便攜版與安裝版功能對照 <a class="header-anchor" href="#附錄-c-便攜版與安裝版功能對照" aria-label="Permalink to &quot;附錄 C 便攜版與安裝版功能對照&quot;">​</a></h3><p>〔注：只列真有差別的幾條，其餘一句「其餘功能完全一致」帶過。表要短，長了反而讓人以爲差別很多。〕</p><hr><p>〔注：定稿後補一段「另請參閲」，鏈到 /zht/docs/install（Rime 掛載）、/zht/docs/ling（靈明方案）、/zht/learn/division（拆分教程）、/zht/docs/faq。〕</p>',156)])])}const b=e(r,[["render",l]]);export{p as __pageData,b as default};
